const remoteJid = $('If').first().json.remoteJid || "";

// Filtra deixando apenas os números
const numeroLimpo = remoteJid.replace(/\D/g, '');

// Pega TODAS as mensagens acumuladas no buffer do Redis (ordem cronológica)
const buffer = $('Deleta').first().json.message || [];

const textos = buffer.map(raw => {
    try {
        return JSON.parse(String(raw).trim()).message || "";
    } catch (error) {
        return ""; // ignora item corrompido em vez de quebrar o fluxo
    }
}).filter(t => t.length > 0);

return {
    json: {
        ...$input.item.json,
        telefone: numeroLimpo,
        texto_usuario: textos.join("\n")
    }
};

// O .first() puxa com segurança o primeiro e único item gerado no início do fluxo
const userMsg = $('Code in JavaScript').first().json.texto_usuario || "Mensagem omitida";

// O .first() puxa a resposta final do agente logo atrás deste nó
const aiMsg = $input.first().json.output || "";

// Puxa o telefone limpo
const telefone = $('Code in JavaScript').first().json.telefone || "";

// Retorna tudo dentro de um Array (colchetes), que é o padrão que o n8n exige no modo All Items
return [{
    json: {
        lembranca: `Chefe: ${userMsg}\nAlfred: ${aiMsg}`,
        telefone: telefone,
        timestamp: Math.floor(Date.now() / 1000)
    }
}];

const body = $input.item.json.body;

// Ignora requisições que não sejam mensagens novas
if (!body || !body.data || body.event !== "messages.upsert") {
    return []; 
}

const data = body.data;
const key = data.key || {};

// Trava APENAS as mensagens enviadas pela própria IA (efeito eco)
if (key.fromMe === true) {
    return []; 
}

let remoteJid = key.remoteJid || "";

// ==========================================
// DICIONÁRIO DE CONTATOS (TRADUTOR DE LIDs)
// ==========================================
const mapaContatos = {
    // "<LID>@lid": "<DDI><DDD><NUMERO>@s.whatsapp.net"
};

if (mapaContatos[remoteJid]) {
    remoteJid = mapaContatos[remoteJid];
}

const telefone = remoteJid.split('@')[0];
const messageId = key.id || "";
const messageType = data.messageType || "";
const pushName = data.pushName || "usuário";
const message = data.message || {};

// Puxa o date_time bruto direto da raiz do body
const timestamp = body.date_time || "";

let texto = "";
let urlMidia = "";
let mimeType = "";

if (messageType === "conversation") {
    texto = message.conversation || "";
} else if (messageType === "extendedTextMessage") {
    texto = message.extendedTextMessage?.text || "";
} else if (messageType === "imageMessage") {
    texto = message.imageMessage?.caption || ""; 
    urlMidia = message.imageMessage?.url || "";
    mimeType = message.imageMessage?.mimetype || "";
} else if (messageType === "audioMessage") {
    urlMidia = message.audioMessage?.url || "";
    mimeType = message.audioMessage?.mimetype || "";
}

return {
    json: {
        telefone: telefone,
        remoteJid: remoteJid,
        fromMe: key.fromMe,
        nome: pushName,
        texto: texto,
        tipo: messageType,
        id: messageId,
        timestamp: timestamp, // <-- Atualizado aqui
        urlMidia: urlMidia,
        mimeType: mimeType,
        messageBruta: data 
    }
};
